struct Square {
    var side: Double
    var area: Double {
        side * side
    }
}
let s = Square(side: 4.0)
print(s.area)

struct ScoreTracker {
    var score: Int = 0 {
        didSet {
            print("Score changed to \(score)")
        }
    }
}
var tracker = ScoreTracker()
tracker.score = 50

struct Temperature {
    var celsius: Double
    var fahrenheit: Double {
        get {
            (celsius * 1.8) + 32.0
        }
        set {
            celsius = (newValue - 32.0) / 1.8
        }
    }
}
var temp = Temperature(celsius: 0.0)
temp.fahrenheit = 212.0
print(temp.celsius)

class Greeter {
    lazy var greeting: String = {
        return "Hello, Friend!"
    }()
}
let g = Greeter()
print(g.greeting)

struct Wallet {
