w.balance = 250

struct Profile {
    var username: String {
        didSet {
            print("didSet fired")
        }
    }
    init(username: String) {
        self.username = username
    }
}
let user = Profile(username: "sam")
print("User: \(user.username)")

struct MathConstants {
